// ClaudeCli.java
public class ClaudeCli {
    private AimbaseConfig config;
    private ConversationHistory history;
    private HttpClientWrapper httpClient;

    public ClaudeCli(AimbaseConfig config) {
        this.config = config;
        this.history = new ConversationHistory();
        this.httpClient = new HttpClientWrapper(config.getApiKey());
    }

    public AimbaseResponse chat(String userMessage) throws ClaudeCliException {
        history.addUserMessage(userMessage);
        AimbaseResponse response = httpClient.sendRequest(config, history.getMessages());
        history.addAssistantMessage(response.getContent());
        return response;
    }

    public void resetHistory() {
        history.clear();
    }
}
